   453→
   454→    let name = type_name::with_defining_ids<CoinType>();
   455→
   456→    let asset = self.assets.load_mut_by_type(name);
   457→    let min_borrow_amount = asset.asset_config().min_borrow_amount();
   458→
   459→    let reserve = accrue_interest<MarketType>(name, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);
   460→    
   461→    let obligation = self.obligations.borrow_mut(obligation_id);
   462→    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
   463→
   464→
   465→    let obligation_old_borrow_amount = obligation.debt(name).unsafe_debt_amount();
   466→
   467→
   468→    let borrow_index = reserve.borrow_index().value();
   469→    let residule = obligation.repay_debt<MarketType, CoinType>(coin.value(), borrow_index);
   470→    obligation.enforce_post_borrow_repay_invariant<MarketType, CoinType>(min_borrow_amount);
   471→    
   472→    // interest updated, should be up to date
   473→    let obligation_new_borrow_amount = if (obligation.has_debt(name)) obligation.debt(name).unsafe_debt_amount() else float::zero();
   474→
   475→    let refund = coin.split(residule, ctx);
   476→
   477→    let emode_group_id = obligation.emode_group();
